CREATE OR REPLACE FUNCTION public.finance_sales_deferred_edit(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s sales_records;cfg finance_schedule_settings;v jsonb;ls jsonb:='[]';issued jsonb:='[]';uses jsonb:='[]';it finance_deferred_items;amt numeric;sold numeric;used numeric;remain numeric;k text;typ text;cashid uuid;clearing uuid;rev uuid;svc uuid;disc uuid;tip uuid;liability uuid;total numeric:=0;ident uuid;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));SELECT * INTO s FROM sales_records WHERE tenant_id=t AND id=(p->>'sales_id')::uuid FOR UPDATE;IF s.id IS NULL OR NOT EXISTS(SELECT 1 FROM venues WHERE tenant_id=t AND name=s.venue AND user_has_venue(auth.uid(),id)) THEN RAISE EXCEPTION 'Sales day unavailable';END IF;
IF EXISTS(SELECT 1 FROM journal_entries WHERE tenant_id=t AND status='posted' AND ((source_type='sales_summary' AND source_id=s.date||'__'||s.venue) OR (source_type='sales' AND source_id=s.id::text))) THEN RETURN finance_sales_deferred_existing(t,p);END IF;
PERFORM finance_assert_open(t,s.date::date);IF s.deferred_feed OR EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND status IN('waiting','approved') AND source_data->>'sales_id'=s.id::text) THEN RAISE EXCEPTION 'Existing deferred schedule requires reconciliation first';END IF;SELECT * INTO cfg FROM finance_schedule_settings WHERE tenant_id=t;v:=p->'values';
FOREACH k IN ARRAY ARRAY['vouchersSold','depositsTaken','vouchersUsed','depositsUsed'] LOOP amt:=coalesce((v->>k)::numeric,0);IF amt<0 OR amt<>round(amt,2) OR (amt>0 AND NOT (CASE WHEN k LIKE 'vouchers%' THEN coalesce(cfg.voucher_enabled,false) ELSE coalesce(cfg.deposit_enabled,false) END)) THEN RAISE EXCEPTION 'Confirm enabled non-negative cent amounts';END IF;END LOOP;
sold:=coalesce((v->>'vouchersSold')::numeric,0)+coalesce((v->>'depositsTaken')::numeric,0);used:=coalesce((v->>'vouchersUsed')::numeric,0)+coalesce((v->>'depositsUsed')::numeric,0);IF sold+used=0 OR sold>s.subtotal THEN RAISE EXCEPTION 'Confirm deferred amounts included in subtotal';END IF;
SELECT account_id INTO cashid FROM account_mapping_rules WHERE tenant_id=t AND rule_type='cash_on_hand' AND match_key=s.venue LIMIT 1;SELECT account_id INTO clearing FROM account_mapping_rules WHERE tenant_id=t AND rule_type='payment_settlement_clearing' AND match_key=s.venue LIMIT 1;SELECT account_id INTO rev FROM account_mapping_rules WHERE tenant_id=t AND rule_type='sales_revenue' AND match_key=s.venue LIMIT 1;SELECT account_id INTO svc FROM account_mapping_rules WHERE tenant_id=t AND rule_type='service_charge' AND match_key=s.venue LIMIT 1;SELECT account_id INTO disc FROM account_mapping_rules WHERE tenant_id=t AND rule_type='sales_discount' AND match_key=s.venue LIMIT 1;SELECT account_id INTO tip FROM account_mapping_rules WHERE tenant_id=t AND rule_type='tips_payable' AND match_key=s.venue LIMIT 1;SELECT id INTO liability FROM chart_of_accounts WHERE tenant_id=t AND code='2300' AND account_type='liability' AND is_active LIMIT 1;
FOREACH k IN ARRAY ARRAY['visa','mastercard','amex','union_pay','jcb','alipay','wechat','payme','cash','deliveroo','foodpanda','keeta'] LOOP amt:=coalesce((to_jsonb(s)->>k)::numeric,0);IF amt<0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'Invalid tender';END IF;total:=total+amt;IF amt>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',CASE WHEN k='cash' THEN cashid ELSE clearing END,'debit',amt,'credit',0,'venue',s.venue,'memo',k));END IF;END LOOP;
IF s.card_tips>0 OR abs(total+s.card_tips-s.total_sales)>.005 OR abs(s.subtotal+s.service_charge+s.discount-s.total_sales)>.005 THEN RAISE EXCEPTION 'Source figures must balance';END IF;
ls:=ls||jsonb_build_array(jsonb_build_object('account_id',rev,'debit',0,'credit',s.subtotal-sold+used,'venue',s.venue));IF sold>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',liability,'debit',0,'credit',sold,'venue',s.venue));END IF;IF used>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',liability,'debit',used,'credit',0,'venue',s.venue));END IF;IF s.service_charge>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',svc,'debit',0,'credit',s.service_charge,'venue',s.venue));END IF;IF s.discount<0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',disc,'debit',abs(s.discount),'credit',0,'venue',s.venue));END IF;IF s.card_tips<0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',tip,'debit',0,'credit',abs(s.card_tips),'venue',s.venue));END IF;
FOREACH typ IN ARRAY ARRAY['voucher','deposit'] LOOP amt:=CASE WHEN typ='voucher' THEN coalesce((v->>'vouchersSold')::numeric,0) ELSE coalesce((v->>'depositsTaken')::numeric,0) END;IF amt>0 THEN INSERT INTO finance_deferred_items(tenant_id,kind,reference,venue,issued_date,amount,expires_on,source_sales_id,status) VALUES(t,typ,'Sales '||s.id||' '||typ,s.venue,s.date::date,amt,CASE WHEN typ='voucher' THEN (s.date::date+make_interval(months=>cfg.voucher_expiry_months))::date ELSE NULL END,s.id,'draft') RETURNING * INTO it;issued:=issued||jsonb_build_array(it.id);END IF;remain:=CASE WHEN typ='voucher' THEN coalesce((v->>'vouchersUsed')::numeric,0) ELSE coalesce((v->>'depositsUsed')::numeric,0) END;FOR it IN SELECT * FROM finance_deferred_items WHERE tenant_id=t AND kind=typ AND venue=s.venue AND status='active' AND issued_date<=s.date::date AND amount>used_amount ORDER BY issued_date,id FOR UPDATE LOOP EXIT WHEN remain<=0;amt:=least(remain,it.amount-it.used_amount);uses:=uses||jsonb_build_array(jsonb_build_object('id',it.id,'amount',amt,'expected_used',it.used_amount));remain:=remain-amt;END LOOP;IF remain>0 THEN RAISE EXCEPTION 'Not enough active deferred balance';END IF;END LOOP;
PERFORM set_config('finance.deferred_edit',s.id::text,true);UPDATE sales_records SET vouchers_sold=coalesce((v->>'vouchersSold')::numeric,0),deposits_taken=coalesce((v->>'depositsTaken')::numeric,0),vouchers_used=coalesce((v->>'vouchersUsed')::numeric,0),deposits_used=coalesce((v->>'depositsUsed')::numeric,0),deferred_feed=true WHERE tenant_id=t AND id=s.id RETURNING * INTO s;PERFORM set_config('finance.deferred_edit','',true);
ident:=finance_schedule_enqueue(t,s.date::date,'sales_deferred','Deferred sales · '||s.venue,'Existing unposted sales; amounts unchanged; monthly approval only','sales-deferred:'||s.id,ls,jsonb_build_object('sales_id',s.id,'sales_fingerprint',md5(to_jsonb(s)::text),'sold_items',issued,'uses',uses),s.receipt_file_url);RETURN ident;END $$;
REVOKE ALL ON FUNCTION public.finance_sales_deferred_edit(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_sales_deferred_edit(uuid,jsonb) TO authenticated;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_deferred_sales_guard()'::regprocedure) INTO def;def:=replace(def,'BEGIN IF TG_OP=', 'BEGIN IF TG_OP=''UPDATE'' AND current_setting(''finance.deferred_edit'',true)=OLD.id::text AND public.finance_schedule_manager(OLD.tenant_id) AND (to_jsonb(NEW)-''vouchers_sold''-''deposits_taken''-''vouchers_used''-''deposits_used''-''deferred_feed''-''updated_at'')=(to_jsonb(OLD)-''vouchers_sold''-''deposits_taken''-''vouchers_used''-''deposits_used''-''deferred_feed''-''updated_at'') AND NOT EXISTS(SELECT 1 FROM journal_entries WHERE tenant_id=OLD.tenant_id AND status=''posted'' AND ((source_type=''sales_summary'' AND source_id=OLD.date||''__''||OLD.venue) OR (source_type=''sales'' AND source_id=OLD.id::text))) THEN RETURN NEW;END IF;IF TG_OP=');EXECUTE def;END $$;